create table app.agent_run_costs (id uuid primary key default gen_random_uuid(), actor_id uuid not null references auth.users(id) on delete cascade, project_id uuid not null references app.projects(id) on delete cascade, task_id text not null, input_digest text not null, operation_id text, provider text, model text, profile text, state text not null check(state in ('reserved','settled','released','billing_indeterminate')), reserved_micros integer not null check(reserved_micros >= 0), settled_micros integer not null default 0 check(settled_micros >= 0), minimum_micros integer, maximum_micros integer, prompt_tokens integer, completion_tokens integer, trace_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(actor_id, project_id, task_id));
alter table app.agent_run_costs enable row level security; alter table app.agent_run_costs force row level security;
create policy agent_run_costs_actor on app.agent_run_costs for all to easy_dashboard_runtime using(actor_id=app.current_actor_id() and app.current_project_member_role(project_id) in ('owner','editor')) with check(actor_id=app.current_actor_id() and app.current_project_member_role(project_id) in ('owner','editor'));
grant select, insert, update on app.agent_run_costs to easy_dashboard_runtime;
